// b7-mcp.go — task-5 full MCP HIL: the REAL b7 loopback drivers pushed
// through the WHOLE MCP pipeline in ONE continuous single-capture run —
// the v1 driver-story closeout evidence. Same three honest process
// layers as b6-mcp.go (go-sdk client over os.Pipe ⇄ `xuansi mcp` ⇄
// `xuansi serve` ⇄ the real board over TCP), XDG-sandboxed, b6 house
// style. The two driver bodies are the VERBATIM fw-repo constants
// (hil/b7-drivers.go, generated by hil/gen-b7-drivers.py from
// xuansi-fw tools/b7-drivers.py AST literal dump — never retyped) and
// their sha256s are asserted at startup so drift is impossible.
//
// One connected story, S0..S10 (task-5 brief):
//
//	S0  prelude+up — bench clean, board reachable, XDG sandbox,
//	    DRIVER SHA ASSERT (i2cecho@1.0.0 1412B / spiloop@1.0.0 1398B /
//	    derived i2cecho@1.1.0), serve up + discovery sweep, mcp up +
//	    SDK initialize, list_boards binds fw_build 775ecaa dual-source
//	S1  lease — custom holder b7-hil, default TCP route, budget
//	    prelude (eval_ms 4000 / event_ms 500 for the script callbacks;
//	    restored at S10)
//	S2  fixture — board_op diag.i2cslave {mode:1} + functional verify:
//	    eval i2c.setup(8/9,100k) + scan == {0x28} (decimal 40)
//	S3  i2cecho@1.0.0 — ws_put (sha bound) -> driver_push (read-back
//	    verified) -> eval require/attach (--@api 1 gate) ->
//	    representative vectors: reg round-trip 63B@0x10 (256B reg-file
//	    model host-side), echo 63B, single-100B-write clamp first-64B;
//	    manifest Active flips to 1.0.0
//	S4  spiloop@1.0.0 — ws_put -> push -> eval require/attach ->
//	    representative vectors: xfer 64B @1MHz (polling bound) == sent,
//	    xfer 65B (DMA edge) == sent, read(8) == 0xFF×8
//	S4b lease cycle — the ops face exposes NO session.reset, so the
//	    ns-0 `_eval` claims on 8/9 + 12/13/14 (S2-S4 evals) are
//	    released the only MCP-reachable way: release (LeaseTeardown
//	    resets holder ns + ns-0) + re-lease (fresh session id) — the
//	    fixture survives session resets (fw s_fix is outside the
//	    session pin table), proven by the S5 script's own scan
//	S5  script resident form — ONE script requiring BOTH drivers,
//	    attaching both, a 250ms measure loop printing per-iteration
//	    echo+xfer lines: capture(stdout) collects them, events_recent
//	    ring shows them live, board_status lists the script, then
//	    script_stop + board_status empty + diag.pins (through the same
//	    capture window) shows 8/9/12/13/14 released, 10/11 held by the
//	    fixture (expected)
//	S6  dynamic tool cross-check — d75884_i2c_scan == eval scan {40}
//	S7  version swap + rollback — ws_put i2cecho@1.1.0 (1.0.0 + the
//	    single `drv.version = "1.1.0"` line) -> push -> hot-swap idiom
//	    (package.loaded nil-out + require) -> drv.version == "1.1.0";
//	    ROLLBACK: driver_push 1.0.0 + hot-swap -> version nil + reg
//	    round-trip still passes + manifest Active == 1.0.0 + fs_read
//	    sha == 1.0.0 sha
//	S8  /drv reconciliation — fs_read of the three expected files
//	    (i2cecho/spiloop sha-bound; b6tiny.lua honestly noted as the
//	    possible batch-6 leftover; the MCP face has no fs.ls)
//	S9  fixture-off negative — diag.i2cslave {mode:0} + fresh
//	    i2c.setup + scan == {}
//	S10 teardown — budget restored, release (ns-0 sweep frees 8/9),
//	    diag.pins via capture#2 shows 8..14 ALL free, mcp EOF exit 0,
//	    serve SIGINT exit 0 + shutdown complete, then the honest
//	    FINDING + out-of-pipeline cleanup: NEITHER the MCP face NOR
//	    the daemon internal API has a file-removal path (fs_write /
//	    fs_read only) — the pipeline can deploy but not clean up — so
//	    the /drv files are removed by a direct TCP REPL connection
//	    (fw-repo tools style, replclient), verified gone, + sandbox
//	    accounting (captures/workspace under the XDG dir)
//
// Single capture, numbered PASS/FAIL per check; failing runs keep their
// own transcripts via b7-full.sh.
package main

import (
	"context"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	mcpsdk "github.com/modelcontextprotocol/go-sdk/mcp"

	"xuansi/internal/replclient"
)

const (
	b7Board    = "d75884"  // the bench board (echo fixture I2C0 8/9 <-> I2C1 10/11 @0x28; SPI self-loop 12<->13, sclk 14)
	b7FwBuild  = "c38b08c" // B10-T2 fix-round-1 canonical (interp delivery; VM-before-wifi boot fix)
	b7Holder   = "b7-hil"  // custom lease holder for this run
	b7TCPEndp  = "xuansi-d75884.local:7777"
	b7Resource = "xuansi://boards/" + b7Board + "/events"
	// B8 item 2: the b7GraceTTL dead constant is GONE. This harness
	// deliberately rides b6's shared serve launcher, which passes
	// --grace-ttl b6GraceTTL (30s) — the S0 check below prints that
	// same b6GraceTTL, so the b7-local copy was never wired to
	// anything (a vestige of the copy-paste, deleted rather than
	// half-wired).
)

// ------------------------------------------------------------- driver sha --

// b7DriverSHAAsserts pins the three driver bodies at startup: the two
// fw-repo constants byte-exact against the controller-ruled sha256s
// (1412B / 1398B, first line --@api 1) and the derived 1.1.0 against
// its generator digest (behavior-keyed assertions follow at S7).
func b7DriverSHAAsserts(h *harness) bool {
	ok := true
	for _, c := range []struct {
		name, body, wantSHA string
		wantBytes           int
	}{
		{"i2cecho@1.0.0 (fw repo I2CECHO_LUA, verbatim)", b7I2CEchoV100, b7I2CEchoV100SHA256, 1412},
		{"spiloop@1.0.0 (fw repo SPILOOP_LUA, verbatim)", b7SPILoopV100, b7SPILoopV100SHA256, 1398},
		{"i2cecho@1.1.0 (derived: +drv.version line)", b7I2CEchoV110, b7I2CEchoV110SHA256, 1436},
	} {
		sum := sha256.Sum256([]byte(c.body))
		got := fmt.Sprintf("%x", sum)
		first := strings.SplitN(c.body, "\n", 2)[0]
		pass := got == c.wantSHA && len(c.body) == c.wantBytes && first == "--@api 1"
		h.check(pass, fmt.Sprintf("S0 driver sha assert: %s -> %dB sha256=%s first-line=%q",
			c.name, len(c.body), got, first))
		ok = ok && pass
	}
	// the 1.1.0 body must differ from 1.0.0 by EXACTLY the one version
	// line (24 bytes: `  drv.version = "1.1.0"\n`) — the minimal diff.
	h.check(len(b7I2CEchoV110)-len(b7I2CEchoV100) == len("  drv.version = \"1.1.0\"\n") &&
		strings.Count(b7I2CEchoV110, "drv.version") == 1,
		fmt.Sprintf("S0 i2cecho@1.1.0 minimal diff: +%d bytes, exactly one drv.version line",
			len(b7I2CEchoV110)-len(b7I2CEchoV100)))
	return ok
}

// ------------------------------------------------------------ fixture model --

// b7FixModel is the host-side mirror of the fixture's 256B reg file
// (xs_i2c.c: every recv cb — first byte = pointer, remaining bytes wrap
// the file; >64B transactions split per 64B receive_buf_depth). Only
// the DETERMINISTIC writes are modeled: the S5 script's echo writes
// land at reg[0x62..0x6A] ('b' pointer), outside every window this HIL
// asserts — noted where it matters.
type b7FixModel struct{ reg [256]byte }

func (m *b7FixModel) reset() { m.reg = [256]byte{} }

func (m *b7FixModel) wrWire(data []byte) {
	for off := 0; off < len(data); off += 64 {
		end := off + 64
		if end > len(data) {
			end = len(data)
		}
		seg := data[off:end]
		ptr := seg[0]
		for _, b := range seg[1:] {
			m.reg[ptr] = byte(b)
			ptr = (ptr + 1) & 0xFF
		}
	}
}

func (m *b7FixModel) window(ptr byte, n int) []byte {
	out := make([]byte, n)
	for i := 0; i < n; i++ {
		out[i] = m.reg[(int(ptr)+i)&0xFF]
	}
	return out
}

// b7Pay is the on-board generator's exact form: byte i = (i*7+seed)%256.
func b7Pay(n, seed int) []byte {
	out := make([]byte, n)
	for i := 1; i <= n; i++ {
		out[i-1] = byte((i*7 + seed) % 256)
	}
	return out
}

// b7LuaPay emits the Lua generator prefix (pattern built on-board —
// large binaries never cross the bridge).
func b7LuaPay(n, seed int) string {
	return fmt.Sprintf("local t={} for i=1,%d do t[i]=string.char((i*7+%d)%%256) end local p=table.concat(t) ", n, seed)
}

// b7Lstr renders bytes as a Lua \ddd literal (ASCII-safe, unambiguous).
func b7Lstr(b []byte) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, c := range b {
		fmt.Fprintf(&sb, "\\%03d", c)
	}
	sb.WriteByte('"')
	return sb.String()
}

// b7CMP is T3/T4's compare tail (first difference reported, else eq).
const b7CMP = `if w==e then return "eq" end ` +
	`for i=1,#w do if w:byte(i)~=e:byte(i) then ` +
	`return string.format("diff@%d got=%d want=%d",i,w:byte(i),e:byte(i)) ` +
	`end end return string.format("len %d/%d",#w,#e)`

// ------------------------------------------------------------------- run --

func runB7MCP(attempt int, daemonBin, runDir string) int {
	h := &harness{}
	ctx := context.Background()

	fmt.Printf("=== b7 task-5 full MCP HIL — %s ===\n", time.Now().Format(time.RFC3339))
	fmt.Printf("attempt: %d (honest count — any failure is fixed and the WHOLE capture rerun)\n", attempt)
	fmt.Printf("board: %s (echo fixture I2C0 8/9 <-> I2C1 10/11 @0x28; SPI self-loop 12<->13 sclk=14; TCP %s; fw expect %s)\n",
		b7Board, b7TCPEndp, b7FwBuild)
	fmt.Printf("drivers: fw-repo bodies, verbatim via hil/gen-b7-drivers.py (AST dump) — sha256 asserted at startup, never retyped\n")
	fmt.Printf("discipline: NEVER read before a write in the same bus epoch (empty-ring read wedges the bus — T3 pin); every vector writes first\n")

	var serve, mcp *b6Proc
	defer func() { // bench restore on every path
		mcp.kill("mcp child")
		serve.kill("daemon")
	}()

	finish := func() int { return finishB7(h, attempt) }

	// ——— S0: prelude + serve + mcp + list_boards ———————————————————
	fmt.Println("\n— S0: prelude — bench clean, sandbox, driver sha asserts, serve+mcp up, list_boards —")
	if out, err := exec.Command("pgrep", "-af", "xuansi").CombinedOutput(); err == nil {
		stale := 0
		for _, ln := range strings.Split(strings.TrimSpace(string(out)), "\n") {
			f := strings.Fields(ln)
			if len(f) >= 2 && strings.Contains(filepath.Base(f[0]), "xuansi") && (f[1] == "serve" || f[1] == "mcp") {
				stale++
				fmt.Printf("  [note] stale xuansi process: %s\n", asciiLine(ln))
			}
		}
		h.check(stale == 0, fmt.Sprintf("no stale xuansi serve/mcp processes on the bench (found %d)", stale))
	} else {
		h.note("pgrep: no xuansi processes found (clean bench)")
	}
	if conn, err := net.DialTimeout("tcp", b7TCPEndp, 3*time.Second); err != nil {
		h.check(false, fmt.Sprintf("board TCP face reachable at %s: %v (USB fallback OUT of scope — opening it reboots the board)", b7TCPEndp, err))
		return finish()
	} else {
		conn.Close()
		h.check(true, fmt.Sprintf("board TCP face reachable at %s (dial only — no reboot, no USB open)", b7TCPEndp))
	}
	if !b7DriverSHAAsserts(h) {
		return finish()
	}

	xdg := filepath.Join(runDir, "xdg")
	if err := os.MkdirAll(xdg, 0o755); err != nil {
		h.check(false, "mkdir run/XDG dir: "+err.Error())
		return finish()
	}
	sock := filepath.Join(runDir, "daemon.sock")
	boardsCfg := filepath.Join(runDir, "boards.conf")
	if err := os.WriteFile(boardsCfg, []byte("# b7-full boards.conf: NO aliases — the dynamic tools take the mac6 prefix (d75884_*)\n"), 0o644); err != nil {
		h.check(false, "write boards.conf: "+err.Error())
		return finish()
	}
	h.note("XDG sandbox: XDG_DATA_HOME=%s (serve captures + mcp workspace land inside; the real user workspace untouched)", xdg)
	h.note("boards.conf: comment-only (no alias) -> dynamic tool prefix = %q", b7Board+"_")

	serve = startB6Daemon(h, daemonBin, sock, boardsCfg, "XDG_DATA_HOME="+xdg)
	if serve == nil {
		return finish()
	}
	ok, last := pollUntil(300*time.Millisecond, 15*time.Second, func() (bool, string) {
		if c, err := net.Dial("unix", sock); err == nil {
			c.Close()
			return true, "sock dialable"
		}
		return false, "sock not bound yet"
	})
	h.check(ok, fmt.Sprintf("daemon sock bound at %s (%s)", sock, last))
	h.check(serve.has("daemon serving"), fmt.Sprintf("daemon reports serving (grace-ttl %s)", b6GraceTTL))
	ok, last = pollUntil(500*time.Millisecond, 45*time.Second, func() (bool, string) {
		return serve.has("initial discovery sweep: 1 board(s)"), "sweep line"
	})
	h.check(ok, fmt.Sprintf("initial discovery sweep found 1 board (%s)", last))

	mcp, mcpR, mcpW := startB6MCP(h, daemonBin, sock, "XDG_DATA_HOME="+xdg)
	if mcp == nil {
		return finish()
	}
	updates := make(chan string, 64)
	cl := mcpsdk.NewClient(&mcpsdk.Implementation{Name: "b7-hil", Version: "1.0"}, &mcpsdk.ClientOptions{
		ResourceUpdatedHandler: func(_ context.Context, r *mcpsdk.ResourceUpdatedNotificationRequest) {
			select {
			case updates <- r.Params.URI:
			default:
			}
		},
		ToolListChangedHandler: func(context.Context, *mcpsdk.ToolListChangedRequest) {},
	})
	b := &b6Client{h: h, cs: nil, updates: updates}
	cs, cerr := cl.Connect(ctx, &mcpsdk.IOTransport{Reader: mcpR, Writer: mcpW}, nil)
	if cerr != nil {
		h.check(false, "MCP client initialize over the child's stdio pipes: "+cerr.Error())
		return finish()
	}
	b.cs = cs
	si := cs.InitializeResult()
	h.check(si != nil && si.ServerInfo.Name == "xuansi",
		fmt.Sprintf("initialize handshake ok: server=%s version=%s (protocol %s)", initField(si, "name"), initField(si, "ver"), initField(si, "proto")))

	var theBoard map[string]any
	ok, last = pollUntil(time.Second, 45*time.Second, func() (bool, string) {
		m, _, isErr, ok := b.call(ctx, 15*time.Second, "xuansi_list_boards", map[string]any{})
		if !ok || isErr {
			return false, fmt.Sprintf("list_boards trouble (isErr=%v)", isErr)
		}
		for _, e := range m["boards"].([]any) {
			if bm, yes := e.(map[string]any); yes && bm["mac6"] == b7Board {
				if fw, _ := bm["fw"].(string); fw != "" {
					theBoard = bm
					return true, "fw populated (hello-enriched)"
				}
				return false, "board listed, fw not yet enriched"
			}
		}
		return false, "board not in list yet"
	})
	if !ok || theBoard == nil {
		h.check(false, fmt.Sprintf("list_boards shows %s with fw populated (%s)", b7Board, last))
		return finish()
	}
	h.check(true, fmt.Sprintf("list_boards shows %s with fw populated (%s)", b7Board, last))
	srcs := []string{}
	if raw, yes := theBoard["sources"].([]any); yes {
		for _, s := range raw {
			if sv, _ := s.(string); sv != "" {
				srcs = append(srcs, sv)
			}
		}
	}
	h.check(len(srcs) == 2 && srcs[0] == "usb" && srcs[1] == "mdns",
		fmt.Sprintf("dual-source merged [usb mdns] (got %v)", srcs))
	fw, _ := theBoard["fw"].(string)
	h.check(fw == b7FwBuild,
		fmt.Sprintf("fw BUILD BINDING: %q == expected %q (flashed fw == fw HEAD bfa8e04 main/, b6's empty-diff binding)", fw, b7FwBuild))

	// ——— S1: lease + budget prelude ——————————————————————————————
	fmt.Println("\n— S1: xuansi_lease holder=b7-hil (default TCP route) + budget prelude —")
	m, text, isErr, _ := b.call(ctx, 30*time.Second, "xuansi_lease", map[string]any{"board": b7Board, "holder": b7Holder})
	sess1, _ := b6Num(m, "session")
	h.check(!isErr && b6Str(m, "board") == b7Board && b6Str(m, "holder") == b7Holder && sess1 > 0,
		fmt.Sprintf("lease holder=%s session=%v (text=%q)", b7Holder, gAny(m, "session"), text))
	h.check(b6Str(m, "transport") == "" && b6Str(m, "warning") == "",
		fmt.Sprintf("lease took the DEFAULT TCP route: transport=%q warning=%q (no usb field, no reboot)", b6Str(m, "transport"), b6Str(m, "warning")))
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_board_op",
		map[string]any{"board": b7Board, "op": "budget.set", "args": map[string]any{"eval_ms": 4000, "event_ms": 500}})
	evMS, _ := b6Num(m, "eval_ms")
	h.check(!isErr && evMS == 4000,
		fmt.Sprintf("[prelude] board_op budget.set eval_ms=4000 event_ms=500 (script callbacks; both restored at S10) -> eval_ms=%v event_ms=%v", evMS, gAny(m, "event_ms")))

	// ——— S2: fixture on + functional verify ———————————————————————
	fmt.Println("\n— S2: board_op diag.i2cslave {mode:1} + functional verify (setup+scan) —")
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_board_op",
		map[string]any{"board": b7Board, "op": "diag.i2cslave", "args": map[string]any{"mode": 1}})
	modeV, _ := b6Num(m, "mode")
	h.check(!isErr && modeV == 1, fmt.Sprintf("diag.i2cslave {mode:1} -> {mode:%v} (echo-slave fixture ON at 0x28, pins 10/11; text=%.80s)", gAny(m, "mode"), text))
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_run_lua", map[string]any{"board": b7Board,
		"code": "bench.i2c.setup(0,{sda=8,scl=9,freq=100000}) local t=bench.i2c.scan(0) return tostring(#t)..\",\"..table.concat(t,\",\")"})
	h.check(!isErr && (b6Str(m, "value") == "1,40" || strings.TrimSpace(b6Str(m, "out")) == "1,40"),
		fmt.Sprintf("[functional verify] eval i2c.setup{8/9,100k} + scan == {0x28} (Lua returns decimal 40): value=%v (text=%.80s)", gAny(m, "value"), text))

	// ——— S3: i2cecho@1.0.0 ————————————————————————————————————————
	fmt.Println("\n— S3: i2cecho@1.0.0 — ws_put (sha bound) -> driver_push -> eval require/attach -> vectors —")
	model := &b7FixModel{}
	m, text, isErr, _ = b.call(ctx, 15*time.Second, "xuansi_ws_put",
		map[string]any{"name": "i2cecho", "version": "1.0.0", "content": b7I2CEchoV100})
	sz, _ := b6Num(m, "size")
	h.check(!isErr && b6Str(m, "sha256") == b7I2CEchoV100SHA256 && int(sz) == 1412,
		fmt.Sprintf("ws_put i2cecho@1.0.0 stored VERBATIM (sha256=%.16s… size=%v == fw-repo body; text=%.80s)", b6Str(m, "sha256"), gAny(m, "size"), text))
	m, text, isErr, _ = b.call(ctx, 15*time.Second, "xuansi_ws_list", map[string]any{})
	stored, active0 := false, ""
	if drs, yes := m["drivers"].([]any); yes {
		for _, d := range drs {
			dm, _ := d.(map[string]any)
			if b6Str(dm, "name") == "i2cecho" {
				active0 = b6Str(dm, "active")
				if vs, ok2 := dm["versions"].([]any); ok2 {
					for _, v := range vs {
						if vm, _ := v.(map[string]any); b6Str(vm, "version") == "1.0.0" {
							stored = true
						}
					}
				}
			}
		}
	}
	h.check(!isErr && stored && active0 == "",
		fmt.Sprintf("ws_list sees i2cecho 1.0.0 stored, active ABSENT before any push (stored=%v active=%q)", stored, active0))
	m, text, isErr, _ = b.call(ctx, 60*time.Second, "xuansi_driver_push",
		map[string]any{"board": b7Board, "name": "i2cecho", "version": "1.0.0"})
	pb, _ := b6Num(m, "bytes")
	h.check(!isErr && b6Str(m, "board") == b7Board && b6Str(m, "path") == "/drv/i2cecho.lua" && int(pb) == 1412 && b6Str(m, "sha256") == b7I2CEchoV100SHA256,
		fmt.Sprintf("driver_push i2cecho@1.0.0 landed /drv/i2cecho.lua, fs_read-back verified (bytes=%v sha=%.16s…; text=%.80s)", gAny(m, "bytes"), b6Str(m, "sha256"), text))
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_run_lua", map[string]any{"board": b7Board, "code": `_M=require("bench.drv.i2cecho") _D=_M.attach({port=0,sda=8,scl=9,freq=100000,addr=0x28}) return type(_M)..","..type(_M.attach)..","..type(_D)..","..type(_D.scan)..","..type(_D.reg_write)..","..type(_D.reg_read)..","..type(_D.echo)`})
	h.check(!isErr && b6Str(m, "value") == "table,function,table,function,function,function,function",
		fmt.Sprintf("eval require+attach through the --@api 1 gate — op surface scan/reg_write/reg_read/echo (value=%v; text=%.80s)", gAny(m, "value"), text))
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_run_lua", map[string]any{"board": b7Board,
		"code": `local t=_D.scan() return tostring(#t)..","..table.concat(t,",")`})
	h.check(!isErr && b6Str(m, "value") == "1,40",
		fmt.Sprintf("drv.scan == {0x28} through the driver face (value=%v)", gAny(m, "value")))

	// S3.5 reg round-trip 63B @0x10 (write precedes read — same-bus-epoch discipline)
	{
		reg, n, seed := 0x10, 63, 13
		payload := b7Pay(n, seed)
		model.wrWire(append([]byte{byte(reg)}, payload...))
		exp := model.window(byte(reg), 64)
		code := b7LuaPay(n, seed) + fmt.Sprintf(`_D.reg_write(%d,p) local w=_D.reg_read(%d,64) local e=`, reg, reg) + b7Lstr(exp) + " " + b7CMP
		m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_run_lua", map[string]any{"board": b7Board, "code": code})
		h.check(!isErr && b6Str(m, "value") == "eq",
			fmt.Sprintf("S3 vector: drv reg round-trip 63B @0x10 — rreg 64B window == 256B-reg-file model (value=%v; text=%.80s)", gAny(m, "value"), text))
	}
	// S3.6 echo 63B (write->read separated transactions; ring full echo)
	// T3 discipline: the reg group above leaves 64B of ring residue (the
	// rreg window-serve does NOT consume the ring — fw fix_request_cb),
	// so the echo group starts from a fixture off->on cycle (ring + TX
	// FIFO + reg file zeroed) + master re-setup + model reset — the
	// exact clean-slate idiom T3 used between its vector groups.
	{
		b7FixtureCycle(h, b, ctx, "S3.5b echo-group clean slate", true)
		model.reset()
		n, seed := 63, 19
		payload := b7Pay(n, seed)
		model.wrWire(payload) // the echo write hits the reg file too — modeled
		code := b7LuaPay(n, seed) + `local w=_D.echo(p) local e=` + b7Lstr(payload) + " " + b7CMP
		m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_run_lua", map[string]any{"board": b7Board, "code": code})
		h.check(!isErr && b6Str(m, "value") == "eq",
			fmt.Sprintf("S3 vector: drv echo 63B round-trip == payload (value=%v; text=%.80s)", gAny(m, "value"), text))
	}
	// S3.7 overflow clamp: single >64B write echoes first 64B (silent cb clamp)
	{
		b7FixtureCycle(h, b, ctx, "S3.6b overflow-group clean slate", true)
		model.reset()
		n, seed := 100, 41
		payload := b7Pay(n, seed)
		// reg-file effect of the clamped single cb is NOT modeled (the
		// cb writes only its first-64B segment's tail into the reg file;
		// T3's rule: reg state is only asserted for <=64B vectors) — this
		// vector asserts the RING echo alone.
		code := b7LuaPay(n, seed) + `bench.i2c.write(0,0x28,p) local w=bench.i2c.read(0,0x28,64) local e=` + b7Lstr(payload[:64]) + " " + b7CMP
		m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_run_lua", map[string]any{"board": b7Board, "code": code})
		h.check(!isErr && b6Str(m, "value") == "eq",
			fmt.Sprintf("S3 vector: single 100B write -> first 64B echoed as-is (single-cb silent clamp; full set in T3 evidence; value=%v)", gAny(m, "value")))
	}
	m, text, isErr, _ = b.call(ctx, 15*time.Second, "xuansi_ws_list", map[string]any{})
	active := b7ActiveVersion(m, "i2cecho")
	h.check(!isErr && active == "1.0.0", fmt.Sprintf("manifest ACTIVE == 1.0.0 right after the verified push (active=%q)", active))

	// ——— S4: spiloop@1.0.0 ————————————————————————————————————————
	fmt.Println("\n— S4: spiloop@1.0.0 — ws_put -> push -> eval require/attach -> vectors —")
	m, text, isErr, _ = b.call(ctx, 15*time.Second, "xuansi_ws_put",
		map[string]any{"name": "spiloop", "version": "1.0.0", "content": b7SPILoopV100})
	sz, _ = b6Num(m, "size")
	h.check(!isErr && b6Str(m, "sha256") == b7SPILoopV100SHA256 && int(sz) == 1398,
		fmt.Sprintf("ws_put spiloop@1.0.0 stored VERBATIM (sha256=%.16s… size=%v; text=%.80s)", b6Str(m, "sha256"), gAny(m, "size"), text))
	m, text, isErr, _ = b.call(ctx, 60*time.Second, "xuansi_driver_push",
		map[string]any{"board": b7Board, "name": "spiloop", "version": "1.0.0"})
	pb, _ = b6Num(m, "bytes")
	h.check(!isErr && b6Str(m, "path") == "/drv/spiloop.lua" && int(pb) == 1398 && b6Str(m, "sha256") == b7SPILoopV100SHA256,
		fmt.Sprintf("driver_push spiloop@1.0.0 landed /drv/spiloop.lua, read-back verified (bytes=%v sha=%.16s…)", gAny(m, "bytes"), b6Str(m, "sha256")))
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_run_lua", map[string]any{"board": b7Board, "code": `_SM=require("bench.drv.spiloop") _SD=_SM.attach({port=0,mosi=12,miso=13,sclk=14,freq=1000000,mode=0}) return type(_SM)..","..type(_SM.attach)..","..type(_SD)..","..type(_SD.xfer)..","..type(_SD.read)..","..type(_SD.write)`})
	h.check(!isErr && b6Str(m, "value") == "table,function,table,function,function,function",
		fmt.Sprintf("eval require+attach spiloop through the --@api 1 gate (value=%v; text=%.80s)", gAny(m, "value"), text))
	for _, v := range []struct {
		tag     string
		n, seed int
	}{
		{tag: "xfer 64B @1MHz (polling bound) == sent", n: 64, seed: 7},
		{tag: "xfer 65B @1MHz (DMA edge) == sent", n: 65, seed: 11},
	} {
		code := b7LuaPay(v.n, v.seed) + `local w=_SD.xfer(p) local e=p ` + b7CMP
		m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_run_lua", map[string]any{"board": b7Board, "code": code})
		h.check(!isErr && b6Str(m, "value") == "eq",
			fmt.Sprintf("S4 vector: drv %s (value=%v)", v.tag, gAny(m, "value")))
	}
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_run_lua", map[string]any{"board": b7Board,
		"code": `local w=_SD.read(8) local e=string.rep(string.char(255),8) ` + b7CMP})
	h.check(!isErr && b6Str(m, "value") == "eq",
		fmt.Sprintf("S4 vector: drv read(8) == 0xFF x 8 (live MISO dummy clocking; value=%v)", gAny(m, "value")))
	m, text, isErr, _ = b.call(ctx, 15*time.Second, "xuansi_ws_list", map[string]any{})
	active = b7ActiveVersion(m, "spiloop")
	h.check(!isErr && active == "1.0.0", fmt.Sprintf("manifest ACTIVE spiloop == 1.0.0 (active=%q)", active))

	// ——— S4b: lease cycle (the MCP-reachable ns-0 eval sweep) ——————
	fmt.Println("\n— S4b: lease cycle — release (LeaseTeardown sweeps ns-0 `_eval`) + re-lease —")
	h.note("the ops face has NO session.reset (T3/T4 used it directly); the only MCP-reachable equivalent is release+re-lease —")
	h.note("  release resets the holder namespace AND ns-0 (lease/session.go teardownNamespaces), freeing the S2-S4 eval claims on 8/9 + 12/13/14 for the S5 script session")
	h.note("  the fixture is OUTSIDE the session pin table (fw s_fix) — it survives the sweep, proven by the script's own scan next")
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_release", map[string]any{"board": b7Board, "holder": b7Holder})
	h.check(!isErr && b6Str(m, "board") == b7Board && b6Str(m, "holder") == b7Holder,
		fmt.Sprintf("release #1 (ns-0 eval sweep; text=%q)", text))
	m, _, isErr, _ = b.call(ctx, 15*time.Second, "xuansi_board_status", map[string]any{"board": b7Board})
	_, hasLease := m["lease"]
	h.check(!isErr && !hasLease, fmt.Sprintf("between leases board_status shows NO lease (lease key %v)", hasLease))
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_lease", map[string]any{"board": b7Board, "holder": b7Holder})
	sess2, _ := b6Num(m, "session")
	h.check(!isErr && sess2 > 0 && sess2 != sess1,
		fmt.Sprintf("re-lease holder=%s -> FRESH session=%v (was %v; every lease gets its own namespace)", b7Holder, gAny(m, "session"), sess1))

	// ——— S5: script resident form ————————————————————————————————
	fmt.Println("\n— S5: script resident form — ONE script, BOTH drivers, measure loop, capture+ring, stop+release —")
	// clean slate for the script's echo loop: the S3 overflow group left
	// ring/FIFO state; a fixture cycle zeroes it (the script's attach
	// re-setups the master) and zeroes the reg file, which also anchors
	// the S7 rollback window model (script echo writes land at
	// reg[0x62..0x6A], outside every asserted window).
	b7FixtureCycle(h, b, ctx, "S5 pre-script clean slate", false)
	model.reset()
	const b7ScriptName = "b7loop"
	const b7Script = `local MI=require("bench.drv.i2cecho") local MD=require("bench.drv.spiloop") ` +
		`local DI=MI.attach({}) local DD=MD.attach({}) ` +
		`print(string.format("b7loop start scan=%d", #DI.scan())) ` +
		`local n=0 ` +
		`bench.timer_ms(250, function() ` +
		`n=n+1 ` +
		`local w=DI.echo("b7loop-"..n) ` +
		`local x=DD.xfer("b7xfer16halfpay!") ` +
		`print(string.format("b7loop iter=%d echo=%s xfer16=%d", n, w, #x)) ` +
		`end) ` +
		`while true do local f=coroutine.yield(); if f then f() end end`
	capCh := b.callAsync("xuansi_capture", map[string]any{"board": b7Board, "source": "stdout", "seconds": float64(6)})
	ok, last = pollUntil(300*time.Millisecond, 10*time.Second, func() (bool, string) {
		return serve.has("capture cap-1 started (" + b7Board + " stdout"), "daemon log: capture started"
	})
	h.check(ok, fmt.Sprintf("stdout capture cap-1 armed board-side through the MCP capture face (%s) — the stdout arming path", last))
	time.Sleep(400 * time.Millisecond) // let the subscription settle before the script starts
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_script_start",
		map[string]any{"board": b7Board, "name": b7ScriptName, "code": b7Script})
	h.check(!isErr, fmt.Sprintf("script_start %s (requires BOTH drivers, attaches both, 250ms measure loop; text=%.100s)", b7ScriptName, text))
	m, text, isErr, _ = b.call(ctx, 15*time.Second, "xuansi_board_status", map[string]any{"board": b7Board})
	h.check(!isErr && strings.Contains(fmt.Sprint(m["scripts"]), b7ScriptName),
		fmt.Sprintf("board_status lists the resident script (scripts=%v)", gAny(m, "scripts")))
	var iters int
	ok, last = pollUntil(500*time.Millisecond, 12*time.Second, func() (bool, string) {
		m, _, isErr, _ := b.call(ctx, 15*time.Second, "xuansi_events_recent",
			map[string]any{"board": b7Board, "source_prefix": "stdout", "limit": 50})
		if isErr {
			return false, "events_recent: " + b6Str(m, "board")
		}
		iters = b7CountLines(m, "b7loop iter=")
		if iters >= 3 {
			return true, fmt.Sprintf("%d measure-loop lines in the ring", iters)
		}
		return false, fmt.Sprintf("%d lines so far (250ms cadence)", iters)
	})
	h.check(ok, fmt.Sprintf("events_recent ring carries the script's per-iteration stdout lines LIVE (%s)", last))
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_script_stop",
		map[string]any{"board": b7Board, "name": b7ScriptName})
	h.check(!isErr, fmt.Sprintf("script_stop %s (text=%.80s)", b7ScriptName, text))
	m, text, isErr, _ = b.call(ctx, 15*time.Second, "xuansi_board_status", map[string]any{"board": b7Board})
	h.check(!isErr && !strings.Contains(fmt.Sprint(m["scripts"]), b7ScriptName),
		fmt.Sprintf("post-stop board_status: script gone (scripts=%v)", gAny(m, "scripts")))
	// diag.pins rides the SAME capture window (its dump is stdout-side)
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_board_op",
		map[string]any{"board": b7Board, "op": "diag.pins"})
	h.check(!isErr, fmt.Sprintf("board_op diag.pins (dump lands on stdout, collected by cap-1; text=%.60s)", text))
	cres := <-capCh
	h.check(cres.ok && !cres.isErr && b6Str(cres.m, "reason") == "limit",
		fmt.Sprintf("stdout capture cap-1 returned {path=%v bytes=%v reason=%v}", gAny(cres.m, "path"), gAny(cres.m, "bytes"), gAny(cres.m, "reason")))
	capPath := b6Str(cres.m, "path")
	capsRoot := filepath.Join(xdg, "xuansi", "captures")
	var capData []byte
	var rdErr error
	if capPath != "" {
		capData, rdErr = os.ReadFile(capPath)
	}
	h.check(capPath != "" && strings.HasPrefix(capPath, capsRoot) && rdErr == nil,
		fmt.Sprintf("capture file inside the XDG sandbox, readable from THIS HIL process (%s, %d bytes)", capPath, len(capData)))
	cont := asciiLine(string(capData))
	h.check(strings.Contains(cont, "b7loop start scan=1"),
		fmt.Sprintf("cap-1 holds the script's start line + fixture-alive proof (scan=1 -> 0x28 answered after the lease cycle)"))
	h.check(iters >= 3 || strings.Count(cont, "b7loop iter=") >= 3,
		fmt.Sprintf("cap-1 holds >=3 measure-loop lines (ring said %d, file says %d)", iters, strings.Count(cont, "b7loop iter=")))
	firstEcho := strings.Contains(cont, "b7loop iter=1 echo=b7loop-1 xfer16=16")
	h.check(firstEcho, "cap-1's first iteration line reads echo=b7loop-1 xfer16=16 (i2c echo AND spi self-loop both alive in the script)")
	busFree := !strings.Contains(cont, "GPIO8") && !strings.Contains(cont, "GPIO9") &&
		!strings.Contains(cont, "GPIO12") && !strings.Contains(cont, "GPIO13") && !strings.Contains(cont, "GPIO14")
	h.check(busFree,
		fmt.Sprintf("diag.pins (in cap-1): 8/9 + 12/13/14 ALL RELEASED by script_stop (busFree=%v)", busFree))
	h.note("the fixture's 10/11 never appear in the pin table (fw s_fix holds them OUTSIDE the session pin registry — T3 evidence: pins(2)=8/9 only); their release is proven by the S9 functional negative")
	h.note("script echo writes landed at reg[0x62..0x6A] ('b' pointer) — outside every window this HIL asserts; count non-deterministic, unmodeled")

	// ——— S6: dynamic tool cross-check ————————————————————————————
	fmt.Println("\n— S6: dynamic tool cross-check — d75884_i2c_scan == eval scan —")
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_run_lua", map[string]any{"board": b7Board,
		"code": `local M=require("bench.drv.i2cecho") local D=M.attach({}) return D.scan()`})
	evalScan := b7JSON(gAny(m, "value"))
	h.check(!isErr && evalScan == "[40]",
		fmt.Sprintf("eval drv.scan() -> %s (decimal 40 == 0x28; re-attach claims 8/9 for ns-0 `_eval`)", evalScan))
	m, text, isErr, _ = b.call(ctx, 30*time.Second, b7Board+"_i2c_scan", map[string]any{"port": float64(0)})
	dynScan := b7JSON(gAny(m, "value"))
	h.check(!isErr && dynScan == evalScan,
		fmt.Sprintf("dynamic tool d75884_i2c_scan{port:0} -> %s == eval result (the caps-driven synthesized-eval path agrees)", dynScan))

	// ——— S7: version swap + rollback —————————————————————————————
	fmt.Println("\n— S7: version swap — ws_put i2cecho@1.1.0 -> push -> hot-swap -> ROLLBACK to 1.0.0 —")
	sum110 := fmt.Sprintf("%x", sha256.Sum256([]byte(b7I2CEchoV110)))
	m, text, isErr, _ = b.call(ctx, 15*time.Second, "xuansi_ws_put",
		map[string]any{"name": "i2cecho", "version": "1.1.0", "content": b7I2CEchoV110})
	sz, _ = b6Num(m, "size")
	h.check(!isErr && b6Str(m, "sha256") == sum110 && int(sz) == 1436,
		fmt.Sprintf("ws_put i2cecho@1.1.0 stored (runtime sha256=%.16s… size=%v; text=%.80s)", b6Str(m, "sha256"), gAny(m, "size"), text))
	m, text, isErr, _ = b.call(ctx, 60*time.Second, "xuansi_driver_push",
		map[string]any{"board": b7Board, "name": "i2cecho", "version": "1.1.0"})
	h.check(!isErr && b6Str(m, "sha256") == sum110,
		fmt.Sprintf("driver_push i2cecho@1.1.0 overwrote /drv/i2cecho.lua, read-back verified (sha=%.16s…)", b6Str(m, "sha256")))
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_run_lua", map[string]any{"board": b7Board,
		"code": `package.loaded["bench.drv.i2cecho"]=nil local M=require("bench.drv.i2cecho") local D=M.attach({}) return tostring(D.version)`})
	h.check(!isErr && b6Str(m, "value") == "1.1.0",
		fmt.Sprintf("HOT-SWAP idiom (package.loaded nil-out + require re-reads /drv from flash) -> drv.version == %q (value=%v)", b6Str(m, "value"), gAny(m, "value")))
	m, text, isErr, _ = b.call(ctx, 15*time.Second, "xuansi_ws_list", map[string]any{})
	active = b7ActiveVersion(m, "i2cecho")
	h.check(!isErr && active == "1.1.0", fmt.Sprintf("manifest ACTIVE == 1.1.0 after the swap (active=%q)", active))
	h.note("rollback = push the older version explicitly (the workspace is the rollback history)")
	m, text, isErr, _ = b.call(ctx, 60*time.Second, "xuansi_driver_push",
		map[string]any{"board": b7Board, "name": "i2cecho", "version": "1.0.0"})
	h.check(!isErr && b6Str(m, "sha256") == b7I2CEchoV100SHA256,
		fmt.Sprintf("ROLLBACK driver_push i2cecho@1.0.0 (read-back sha=%.16s…)", b6Str(m, "sha256")))
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_run_lua", map[string]any{"board": b7Board,
		"code": `package.loaded["bench.drv.i2cecho"]=nil local M=require("bench.drv.i2cecho") local D=M.attach({}) return tostring(D.version)`})
	h.check(!isErr && b6Str(m, "value") == "nil",
		fmt.Sprintf("hot-swap after rollback -> drv.version ABSENT for 1.0.0 (tostring=%q — behavior-keyed, not sha-keyed)", b6Str(m, "value")))
	{
		reg, n, seed := 0x20, 16, 5
		payload := b7Pay(n, seed)
		model.wrWire(append([]byte{byte(reg)}, payload...))
		exp := model.window(byte(reg), 64)
		code := b7LuaPay(n, seed) + fmt.Sprintf(`_D=require("bench.drv.i2cecho").attach({}) _D.reg_write(%d,p) local w=_D.reg_read(%d,64) local e=`, reg, reg) + b7Lstr(exp) + " " + b7CMP
		m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_run_lua", map[string]any{"board": b7Board, "code": code})
		h.check(!isErr && b6Str(m, "value") == "eq",
			fmt.Sprintf("post-rollback reg round-trip 16B @0x20 still passes on the 1.0.0 body (window==model; value=%v)", gAny(m, "value")))
	}
	m, text, isErr, _ = b.call(ctx, 15*time.Second, "xuansi_ws_list", map[string]any{})
	active = b7ActiveVersion(m, "i2cecho")
	h.check(!isErr && active == "1.0.0", fmt.Sprintf("manifest ACTIVE back to 1.0.0 (active=%q)", active))

	// ——— S8: /drv reconciliation via fs_read ——————————————————————
	fmt.Println("\n— S8: /drv reconciliation — fs_read the expected files (no fs.ls in the MCP face) —")
	for _, f := range []struct {
		path, wantSHA, note string
	}{
		{"/drv/i2cecho.lua", b7I2CEchoV100SHA256, "post-rollback active body"},
		{"/drv/spiloop.lua", b7SPILoopV100SHA256, "pushed at S4, never swapped"},
	} {
		m, text, isErr, _ = b.call(ctx, 15*time.Second, "xuansi_fs_read", map[string]any{"board": b7Board, "path": f.path})
		okSha := false
		if !isErr {
			if raw, derr := base64.StdEncoding.DecodeString(b6Str(m, "data_b64")); derr == nil {
				okSha = fmt.Sprintf("%x", sha256.Sum256(raw)) == f.wantSHA
			}
		}
		h.check(okSha, fmt.Sprintf("fs_read %s sha256 == %s (%s)", f.path, f.wantSHA[:16]+"…", f.note))
	}
	m, text, isErr, _ = b.call(ctx, 15*time.Second, "xuansi_fs_read", map[string]any{"board": b7Board, "path": "/drv/b6tiny.lua"})
	if !isErr {
		h.note("fs_read /drv/b6tiny.lua: PRESENT (the batch-6 leftover, honestly expected — removed at S10; %.40s…)", text)
	} else {
		h.note("fs_read /drv/b6tiny.lua: absent (the possible batch-6 leftover is not on this board)")
	}
	h.note("reconciliation method: the MCP face has no fs.ls — the three expected /drv files are reconciled by fs_read sha (b6tiny honestly noted either way)")

	// ——— S9: fixture-off negative ————————————————————————————————
	fmt.Println("\n— S9: fixture-off negative — diag.i2cslave {mode:0} -> scan == {} —")
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_board_op",
		map[string]any{"board": b7Board, "op": "diag.i2cslave", "args": map[string]any{"mode": 0}})
	modeV, _ = b6Num(m, "mode")
	h.check(!isErr && modeV == 0, fmt.Sprintf("diag.i2cslave {mode:0} -> {mode:%v} (fixture OFF — slave 0x28 gone, pins 10/11 released)", gAny(m, "mode")))
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_run_lua", map[string]any{"board": b7Board,
		"code": "bench.i2c.setup(0,{sda=8,scl=9,freq=100000}) local t=bench.i2c.scan(0) return tostring(#t)..\",\"..table.concat(t,\",\")"})
	h.check(!isErr && (b6Str(m, "value") == "0," || strings.TrimSpace(b6Str(m, "out")) == "0,"),
		fmt.Sprintf("fresh i2c.setup after off + scan == {} (value=%v — the negative: no 0x28 without the fixture)", gAny(m, "value")))

	// ——— S10: teardown ————————————————————————————————————————————
	fmt.Println("\n— S10: teardown — budget restore, release+sweep, pins ALL free (capture#2), mcp EOF, serve SIGINT, /drv cleanup + sandbox —")
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_board_op",
		map[string]any{"board": b7Board, "op": "budget.set", "args": map[string]any{"eval_ms": 200, "event_ms": 50}})
	evMS, _ = b6Num(m, "eval_ms")
	h.check(!isErr && evMS == 200, fmt.Sprintf("budget restored eval_ms=200 event_ms=50 (board as found; eval_ms=%v)", evMS))
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_release", map[string]any{"board": b7Board, "holder": b7Holder})
	h.check(!isErr && b6Str(m, "board") == b7Board && b6Str(m, "holder") == b7Holder,
		fmt.Sprintf("final release (holder ns + ns-0 `_eval` swept -> 8/9 free; text=%q)", text))
	h.check(serve.count("reason=released") >= 2, fmt.Sprintf("daemon log: lease teardowns reason=released (count=%d)", serve.count("reason=released")))
	m, _, isErr, _ = b.call(ctx, 15*time.Second, "xuansi_board_status", map[string]any{"board": b7Board})
	_, hasLease = m["lease"]
	h.check(!isErr && !hasLease, fmt.Sprintf("post-release board_status shows NO lease (lease key %v)", hasLease))

	// the pins dump is an ops-face read (lease-gated) printed to stdout —
	// take a brief second lease purely for capture#2 + diag.pins, then
	// release it (honest: the fresh lease claims nothing itself).
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_lease", map[string]any{"board": b7Board, "holder": b7Holder})
	h.check(!isErr, fmt.Sprintf("brief re-lease for the pins read (a fresh lease claims nothing; text=%.60s)", text))
	cap2Ch := b.callAsync("xuansi_capture", map[string]any{"board": b7Board, "source": "stdout", "seconds": float64(3)})
	ok, last = pollUntil(300*time.Millisecond, 10*time.Second, func() (bool, string) {
		return serve.has("capture cap-2 started (" + b7Board + " stdout"), "daemon log: capture started"
	})
	h.check(ok, fmt.Sprintf("stdout capture cap-2 armed for the pins dump (%s)", last))
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_board_op",
		map[string]any{"board": b7Board, "op": "diag.pins"})
	h.check(!isErr, fmt.Sprintf("board_op diag.pins post-release (dump on stdout via cap-2; text=%.60s)", text))
	res2 := <-cap2Ch
	pinDump := ""
	if res2.ok && !res2.isErr {
		if d2, e2 := os.ReadFile(b6Str(res2.m, "path")); e2 == nil {
			pinDump = asciiLine(string(d2))
		}
	}
	if pinDump != "" {
		var busy []string
		for _, p := range []string{"GPIO8", "GPIO9", "GPIO10", "GPIO11", "GPIO12", "GPIO13", "GPIO14"} {
			if strings.Contains(pinDump, p) {
				busy = append(busy, p)
			}
		}
		h.check(len(busy) == 0, fmt.Sprintf("final diag.pins: 8/9/10/11/12/13/14 ALL FREE (busy=%v; dump head: %.60s)", busy, strings.TrimSpace(pinDump)))
	} else {
		h.check(false, fmt.Sprintf("final diag.pins capture readable (res.ok=%v isErr=%v)", res2.ok, res2.isErr))
	}
	m, text, isErr, _ = b.call(ctx, 30*time.Second, "xuansi_release", map[string]any{"board": b7Board, "holder": b7Holder})
	h.check(!isErr, fmt.Sprintf("release #2 — the bench is left UNLEASED (text=%.60s)", text))

	if err := cs.Close(); err != nil {
		h.note("client session close: %v (proceeding to EOF wait)", err)
	}
	select {
	case <-mcp.exited:
		code, werr := mcp.exitStats()
		h.check(code == 0 && werr == nil,
			fmt.Sprintf("xuansi mcp exited clean on stdin EOF (code=%d waitErr=%v)", code, werr))
		h.check(!mcp.has("xuansi mcp:"), "mcp stderr carries no error line (clean EOF path)")
	case <-time.After(8 * time.Second):
		h.check(false, "xuansi mcp did not exit within 8s of the client close (EOF on stdin)")
		mcp.kill("mcp EOF timeout")
	}
	if !serve.sigintAndWait(h, 20*time.Second) {
		return finish()
	}
	code, werr := serve.exitStats()
	h.check(code == 0 && werr == nil, fmt.Sprintf("daemon exited clean (code=%d waitErr=%v)", code, werr))
	h.check(serve.shutdownDone(), "daemon's own final log line: 'shutdown complete' (no goroutine-leak complaint)")
	_, serr := os.Stat(sock)
	h.check(os.IsNotExist(serr), fmt.Sprintf("sock file removed at exit (stat err=%v)", serr))

	// FINDING + honest out-of-pipeline cleanup: no removal path exists in
	// the MCP face (fs_write/fs_read only) or the daemon internal API
	// (proto.go request types) — the pipeline can deploy but not clean
	// up. The /drv files are removed by a DIRECT TCP REPL connection,
	// fw-repo-tools style, clearly OUTSIDE the MCP pipeline.
	fmt.Println("\n— S10b: FINDING + out-of-pipeline /drv cleanup (direct TCP REPL, honestly labeled) —")
	h.note("FINDING: neither the MCP static face (17 tools) nor the daemon internal API has a file-removal request —")
	h.note("  the driver pipeline can deploy (ws_put/driver_push) and read back (fs_read) but cannot CLEAN UP /drv; reported in the task report")
	b7CleanupDRV(h, ctx)

	// sandbox accounting
	wsRoot := filepath.Join(xdg, "xuansi", "workspace")
	h.note("XDG sandbox accounting:")
	b7NoteTree(h, capsRoot, "captures")
	b7NoteTree(h, wsRoot, "workspace")
	for _, f := range []string{"i2cecho@1.0.0.lua", "i2cecho@1.1.0.lua", "spiloop@1.0.0.lua"} {
		if _, err := os.Stat(filepath.Join(wsRoot, "drivers", f)); err == nil {
			h.note("  workspace/drivers/%s present (the rollback history)", f)
		}
	}
	man, manErr := os.ReadFile(filepath.Join(wsRoot, "manifest.json"))
	manParses := false
	if manErr == nil {
		var j map[string]any
		manParses = json.Unmarshal(man, &j) == nil
	}
	h.check(manErr == nil && manParses, fmt.Sprintf("workspace manifest.json parses under the sandbox (root=%s)", wsRoot))

	return finish()
}

// finishB7 prints the closing verdict.
func finishB7(h *harness, attempt int) int {
	code := h.finish("b7-mcp")
	if h.fail == 0 {
		fmt.Printf("=== ALL PASS — task-5 v1 driver-story closeout: real loopback drivers through the whole MCP pipeline, single capture (attempt %d, S0..S10) ===\n", attempt)
	}
	return code
}

// ------------------------------------------------------------- b7 helpers --

// b7FixtureCycle is T3's clean-slate idiom through the MCP pipeline:
// diag.i2cslave off->on (the fixture's echo ring, TX FIFO and 256B reg
// file are all zeroed by the recreate), optionally + master re-setup
// (same-owner re-entry). Required between vector groups: the rreg
// window-serve does NOT consume the ring (fw fix_request_cb), so
// residue from a reg group would block later echo writes (ring full ->
// drop) and poison reads — exactly what T3's fixture_reset guarded
// against. reinit=false when the NEXT bus user is a fresh session (the
// S5 script): an eval re-setup would re-claim 8/9 for ns-0 `_eval` and
// block the script session's attach — the script's own attach is the
// setup there.
func b7FixtureCycle(h *harness, b *b6Client, ctx context.Context, tag string, reinit bool) bool {
	okay := true
	for _, mode := range []float64{0, 1} {
		m, text, isErr, _ := b.call(ctx, 30*time.Second, "xuansi_board_op",
			map[string]any{"board": b7Board, "op": "diag.i2cslave", "args": map[string]any{"mode": mode}})
		mv, _ := b6Num(m, "mode")
		if !(!isErr && mv == mode) {
			h.check(false, fmt.Sprintf("%s: diag.i2cslave {mode:%v} -> {mode:%v isErr=%v} (text=%.60s)", tag, mode, gAny(m, "mode"), isErr, text))
			okay = false
		}
	}
	if reinit {
		m, text, isErr, _ := b.call(ctx, 30*time.Second, "xuansi_run_lua", map[string]any{"board": b7Board,
			"code": `bench.i2c.setup(0,{sda=8,scl=9,freq=100000}) return "reinit-ok"`})
		if !(!isErr && (b6Str(m, "value") == "reinit-ok" || strings.Contains(b6Str(m, "out"), "reinit-ok"))) {
			h.check(false, fmt.Sprintf("%s: master re-setup after the cycle (value=%v text=%.60s)", tag, gAny(m, "value"), text))
			okay = false
		}
	}
	if okay {
		h.note("%s: fixture off->on (ring/TX FIFO/reg file zeroed)%s", tag, map[bool]string{true: " + master re-setup", false: " (master setup left to the next owner)"}[reinit])
	}
	return okay
}

// b7JSON renders any bridged value as compact JSON for comparison.
func b7JSON(v any) string {
	b, err := json.Marshal(v)
	if err != nil {
		return fmt.Sprint(v)
	}
	return string(b)
}

// b7ActiveVersion pulls one driver's ACTIVE version from a ws_list reply.
func b7ActiveVersion(m map[string]any, name string) string {
	if drs, yes := m["drivers"].([]any); yes {
		for _, d := range drs {
			if dm, _ := d.(map[string]any); b6Str(dm, "name") == name {
				return b6Str(dm, "active")
			}
		}
	}
	return ""
}

// b7CountLines counts stdout ring events whose payload contains marker.
func b7CountLines(m map[string]any, marker string) int {
	n := 0
	for _, e := range evsList(m) {
		em, _ := e.(map[string]any)
		if b6Str(em, "source") != "stdout" {
			continue
		}
		if strings.Contains(b7JSON(em["data"]), marker) {
			n++
		}
	}
	return n
}

// b7NoteTree lists one sandbox subtree into the transcript (accounting).
func b7NoteTree(h *harness, root, label string) {
	ents, err := os.ReadDir(root)
	if err != nil {
		h.note("  %s: (unreadable: %v)", label, err)
		return
	}
	names := []string{}
	for _, e := range ents {
		names = append(names, e.Name())
	}
	h.note("  %s/ (%d entries): %s", label, len(names), strings.Join(names, ", "))
}

// b7CleanupDRV removes the /drv files over a direct TCP REPL connection
// (the daemon is already down; the board's controller slot is free).
func b7CleanupDRV(h *harness, ctx context.Context) {
	var c *replclient.Client
	var info *replclient.HelloInfo
	var err error
	for i := 0; i < 8; i++ { // the board processes the daemon's FIN async — retry the hello
		if c, err = replclient.DialTCP(b7TCPEndp, replclient.DialOpts{Log: dialLog}); err != nil {
			continue
		}
		if info, err = c.Hello(false, "b7-t5-clean"); err == nil && info.Role == "controller" {
			break
		}
		_ = c.Close()
		c = nil
		time.Sleep(500 * time.Millisecond)
	}
	if c == nil || info == nil || info.Role != "controller" {
		role := "<no hello>"
		if info != nil {
			role = info.Role
		}
		h.check(false, fmt.Sprintf("cleanup REPL: controller hello at %s (last err=%v role=%s)", b7TCPEndp, err, role))
		return
	}
	defer c.Close()
	h.check(info.FwBuild == b7FwBuild && info.ProtocolVer == 5,
		fmt.Sprintf("cleanup REPL hello binds fw_build=%s protocol_ver=%d role=%s", info.FwBuild, info.ProtocolVer, info.Role))

	rmTargets := []string{"/drv/i2cecho.lua", "/drv/spiloop.lua"}
	for _, p := range rmTargets {
		_, err := c.Op(ctx, "fs.rm", map[string]any{"path": p})
		h.check(err == nil, fmt.Sprintf("fs.rm %s (direct REPL, outside the MCP pipeline; err=%v)", p, err))
	}
	if _, err := c.Op(ctx, "fs.rm", map[string]any{"path": "/drv/b6tiny.lua"}); err == nil {
		h.note("fs.rm /drv/b6tiny.lua: removed (the batch-6 leftover was present)")
	} else {
		h.note("fs.rm /drv/b6tiny.lua: refused (%v) — reading back to classify", err)
		if _, rerr := c.FsRead(ctx, "/drv/b6tiny.lua"); rerr != nil {
			h.note("fs.read /drv/b6tiny.lua errors too (%v) — the file was never there; board already clean", rerr)
		} else {
			h.check(false, "fs.rm /drv/b6tiny.lua failed but the file still reads (leftover persists)")
		}
	}
	for _, p := range rmTargets {
		if _, rerr := c.FsRead(ctx, p); rerr != nil {
			h.check(true, fmt.Sprintf("fs.read %s post-rm errors (%v) — file GONE, /drv as found", p, rerr))
		} else {
			h.check(false, fmt.Sprintf("fs.read %s post-rm still succeeds — removal did not land", p))
		}
	}
}
